// Photos of the sosialisasi POIs, embedded as data-URIs so the prototype stays
// self-contained (§2/§3: no external fetch, no shared public/ asset). Keyed by
// the event's `art`; a POI without a photo falls back to the drawn scene in
// `poi-image.tsx`. This module is only imported from the (lazy-loaded)
// Sosialisasi screen, so its weight never reaches any other page.

import type { PoiArt } from './leads'

export const POI_PHOTO: Partial<Record<PoiArt, string>> = {
  'pasar-ikan': 'data:image/webp;base64,',
  warung: 'data:image/webp;base64,',
}
